#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000

char *getResult(char s[]);

int main() {
    char s[MAX_SIZE];
    gets(s);

    puts(getResult(s));

    return 0;
}

int cmp(const void *a, const void *b) {
    return (*(char *) a) - (*(char *) b);
}

char *getResult(char s[]) {
    int len = strlen(s);

    char minS[len + 1];
    strcpy(minS, s);

    qsort(minS, len, sizeof(char), cmp);

    if (strcmp(minS, s) == 0) {
        return s;
    }

    for (int i = 0; i < len; i++) {
        if(s[i] != minS[i]) {
            char tmp = s[i];
            s[i] = minS[i];

            int swapIdx = strrchr(s, minS[i]) - s;
            s[swapIdx] = tmp;
            break;
        }
    }

    return s;
}
